<template>
    <div class="create-image-character-dialog" id="create-image-character-dialog">
        <el-dialog v-model="dialogVisible" width="45%" class="create-image-character-dialog-container" append-to-body
            :show-close="false">
            <template #header>
                <!-- 标题区域 -->
                <div class="dialog-header">
                    <h2 class="dialog-title">{{ t("createTool") }}</h2>
                    <div class="header-actions">
                        <l-img @click="handleClose" src="/static/images/close_icon.png" w="20px" h="20px"
                            class="close-btn"></l-img>
                    </div>
                </div>
            </template>
            <div class="dialog-background-box">
                <div class="dialog-background">
                    <!-- 表单内容区域 -->
                    <el-form ref="imageToolFormRef" :model="imageToolData" :rules="rules" label-position="top"
                        class="form-container">

                        <!-- 工具标题 -->
                        <div class="form-field">
                            <el-form-item prop="title">
                                <div class="form-field-label">
                                    {{ t("title") }}
                                    <span class="required-star"> *</span>
                                </div>
                                <el-input v-model="imageToolData.title" :placeholder="t('titlePlaceholder')"
                                    :maxlength="30" :show-word-limit="false" class="title-input"/>
                            </el-form-item>
                        </div>

                        <!-- 工具描述 -->
                        <div class="form-field">
                            <el-form-item prop="description">
                                <div class="description-container">
                                    <div class="form-field-label">
                                        {{ t("description") }}
                                        <span class="required-star"> *</span>
                                    </div>
                                    <div class="description-tip">
                                        {{ t("maxCharacters") }}
                                    </div>
                                </div>

                                <el-input v-model="imageToolData.description" type="textarea"
                                    :placeholder="t('descriptionPlaceholder')" :maxlength="120" show-word-limit
                                    :input-style="{ height: pxToRem('100px') }" />
                            </el-form-item>
                        </div>

                        <!-- 最大图片数量 -->
                        <div class="form-field">
                            <el-form-item prop="max_images">
                                <div class="max-images-container">
                                    <div class="form-field-label">
                                        {{ t("maxImagesPerAnalysis") }}
                                    </div>
                                    <div class="image-count-container">
                                        <div class="image-count-selector">
                                            <button type="button" class="count-btn decrease"
                                                :disabled="imageToolData.max_images <= 1" @click="decreaseImageCount">
                                                <span class="minus-icon">−</span>
                                            </button>
                                            <div class="count-display">
                                                {{ imageToolData.max_images }}
                                            </div>
                                            <button type="button" class="count-btn increase"
                                                :disabled="imageToolData.max_images >= 6" @click="increaseImageCount">
                                                <span class="minus-icon">+</span>
                                            </button>
                                        </div>
                                    </div>
                                </div>

                            </el-form-item>
                        </div>

                        <!-- 工具提示词 -->
                        <div class="form-field">
                            <el-form-item prop="prompt">
                                <div class="form-field-label">
                                    {{ t("prompt") }}
                                    <span class="required-star"> *</span>
                                </div>
                                <el-input v-model="imageToolData.prompt" type="textarea" :rows="9"
                                    :placeholder="t('promptPlaceholder')" class="prompt-textarea" />
                            </el-form-item>
                        </div>
                    </el-form>
                </div>
            </div>

            <!-- 底部操作栏 -->
            <template #footer>
                <div class="footer-container">
                    <div class="footer-content">
                        <div class="footer-actions">
                            <div class="action-buttons">
                                <el-button @click="handleClose" size="large" class="cancel-btn">
                                    {{ t("cancel") }}
                                </el-button>
                                <el-button @click="submitForm" type="primary" size="large" class="submit-btn"
                                    :loading="isSubmitting">
                                    {{ isSubmitting ? t("loading") : t("createTool") }}
                                </el-button>
                            </div>
                        </div>
                    </div>
                </div>
            </template>
        </el-dialog>
    </div>
</template>

<script setup>
import { ref, reactive, watch, computed, nextTick } from 'vue';
import { useI18n } from 'vue-i18n';
import { ElMessage } from 'element-plus';
import LImg from '@/components/l-img.vue';
import { ApiImageTool } from '@/api/api-image-tool';
import { isFormDataIdentical } from '@/utils/util.js';
import { pxToRem } from '@/utils/px-to-rem';

const { t } = useI18n();

// Props 定义
const props = defineProps({
    visible: {
        type: Boolean,
        default: false
    },
    // 新增：快速填写数据prop
    fillData: {
        type: Object,
        default: null,
    },
});

// Emits 定义
const emit = defineEmits(['update:visible', 'create', 'cancel']);

// 图片工具字段映射配置
const IMAGE_TOOL_FIELD_MAPPINGS = [
  { current: 'title', original: ['title', 'name'] },
  { current: 'description', original: 'description' },
  { current: 'prompt', original: ['prompt', 'content', 'preview'] },
  { current: 'max_images', original: ['max_images', 'maxImages'], defaultValue: 1 }
];

// 响应式数据
const dialogVisible = ref(false);
const isSubmitting = ref(false);
const imageToolFormRef = ref(null);

// 图片工具数据
const imageToolData = ref({
    title: '',
    description: '',
    prompt: '',
    max_images: 4
});

// 表单验证规则
const rules = reactive({
    title: [
        {
            required: true,
            message: t("title") + " " + t("isRequired"),
            trigger: "blur",
        },
        {
            min: 1,
            max: 64,
            message: t("lengthRange", { min: 1, max: 64 }),
            trigger: "blur",
        },
    ],
    description: [
        {
            required: true,
            message: t("description") + " " + t("isRequired"),
            trigger: "blur",
        },
        {
            min: 1,
            max: 120,
            message: t("lengthRange", { min: 1, max: 120 }),
            trigger: "blur",
        },
    ],
    prompt: [
        {
            required: true,
            message: t("prompt") + " " + t("isRequired"),
            trigger: "blur",
        },
        {
            min: 10,
            message: t("lengthRange", { min: 10, max: 2000 }),
            trigger: "blur",
        },
    ],
});

// 监听props.visible变化
watch(
    () => props.visible,
    async (newVal) => {
        dialogVisible.value = newVal;
        if (newVal) {
            // 弹窗打开时，等待 DOM 更新完成后再填充数据
            await nextTick();
            if (props.fillData) {
                fillFormWithData();
            } else {
                // 如果没有数据，重置表单
                resetForm();
            }
        }
    }
);

// 监听dialogVisible变化
watch(
    () => dialogVisible.value,
    (newVal) => {
        emit("update:visible", newVal);
    }
);

// 监听快速填写数据变化
watch(
    () => props.fillData,
    async (newData) => {
        if (newData && dialogVisible.value) {
            // 等待 DOM 更新完成后再填充数据
            await nextTick();
            fillFormWithData();
        }
    },
    { deep: true }
);

// 重置表单
const resetForm = () => {
    imageToolData.value = {
        title: '',
        description: '',
        prompt: '',
        max_images: 4
    };
    if (imageToolFormRef.value) {
        imageToolFormRef.value.resetFields();
    }
};

// 关闭弹窗
const handleClose = () => {
    dialogVisible.value = false;
    emit('cancel');
    resetForm();
};

// 增加图片数量
const increaseImageCount = () => {
    if (imageToolData.value.max_images < 6) {
        imageToolData.value.max_images++;
    }
};

// 减少图片数量
const decreaseImageCount = () => {
    if (imageToolData.value.max_images > 1) {
        imageToolData.value.max_images--;
    }
};

// 提交表单
const submitForm = async () => {
    if (!imageToolFormRef.value) return;

    await imageToolFormRef.value.validate(async (valid) => {
        if (valid) {
            try {
                // 检查是否有快速填写数据，且当前表单数据与快速填写数据完全一致
                if (props.fillData) {
                    const isDataIdentical = isFormDataIdentical(
                        imageToolData.value,
                        props.fillData,
                        IMAGE_TOOL_FIELD_MAPPINGS
                    );
                    
                    if (isDataIdentical) {
                        ElMessage.warning(t('dataUnchangedError'));
                        return;
                    }
                }
                
                isSubmitting.value = true;
                
                const apiData = {
                    title: imageToolData.value.title,
                    description: imageToolData.value.description,
                    prompt: imageToolData.value.prompt,
                    max_images: imageToolData.value.max_images
                };

                // 调用创建图片工具API
                const response = await ApiImageTool.createImageTool(apiData);

                if (response && response.code === 200) {
                    // 创建工具数据对象（用于前端显示）
                    // const tool = {
                    //     id: response.data.id,
                    //     title: response.data.title,
                    //     name: response.data.title,
                    //     description: response.data.description,
                    //     prompt: response.data.prompt,
                    //     prompt_preview: response.data.prompt_preview || response.data.prompt,
                    //     max_images: response.data.max_images,
                    //     creator_id: response.data.creator_id,
                    //     chat_count: response.data.chat_count || 0,
                    //     usage_count: response.data.usage_count || 0,
                    //     created_at: response.data.created_at || new Date().toISOString()
                    // };

                    // 发送创建成功事件
                    emit("create", 'tool');
                    // 关闭弹窗
                    dialogVisible.value = false;
                    // 重置表单
                    resetForm();
                } else {
                    // 处理不同的错误码
                    handleApiError(response);
                }
            } catch (error) {
                console.error('Failed to create image tool:', error);
                handleNetworkError(error);
            } finally {
                isSubmitting.value = false;
            }
        }
    });
};

// API错误处理
const handleApiError = (response) => {
    const errorCode = response?.code;
    const errorMessage = response?.message || 'Unknown error';
    
    switch (errorCode) {
        case 400:
            ElMessage.error(t('validationError') + ': ' + errorMessage);
            break;
        case 401:
            ElMessage.error(t('authError'));
            break;
        case 403:
            ElMessage.error(t('permissionError'));
            break;
        case 409:
            ElMessage.error(t('toolNameExists'));
            break;
        case 429:
            ElMessage.error(t('rateLimitError'));
            break;
        case 500:
            ElMessage.error(t('serverError'));
            break;
        default:
            ElMessage.error(t('createError') + ': ' + errorMessage);
    }
};

// 网络错误处理
const handleNetworkError = (error) => {
    if (error.name === 'NetworkError' || error.message.includes('fetch')) {
        ElMessage.error(t('networkError'));
    } else if (error.name === 'TimeoutError') {
        ElMessage.error(t('timeoutError'));
    } else {
        ElMessage.error(error.message || t('createError'));
    }
};


// 填充数据到表单（帮助用户快速填写）
const fillFormWithData = () => {
    if (props.fillData) {
        imageToolData.value = {
            title: props.fillData.title,
            description: props.fillData.description || "",
            prompt: props.fillData.prompt || props.fillData.content ||  "",
            max_images: props.fillData.max_images || props.fillData.maxImages || 1,
        };
        
        
        // 清除表单验证错误
        if (imageToolFormRef.value) {
            imageToolFormRef.value.clearValidate();
        }
    }
};
</script>


