<template>
    <div class="image-tool-page" :style="pageStyle">
        <!-- 左侧聊天列表 -->
        <CharacterSidebar :title="t('imageAnalysis')" :selected-item="currentTool"
            :load-items-api="ApiImageTool.getImageToolList" :format-item="formatImageToolItem"
            :create-button-text="t('createTool')" :empty-text="t('noToolsAvailable')"
            :detail-icon="'/static/images/menu_dots.png'" :stats-icon="'/static/images/image_chat/usage_icon.png'"
            :mock-data="mockImageTools" @select="handleToolSelect" @create="handleCreateTool"
            @show-details="handleShowToolDetails" ref="toolSidebarRef" />

        <!-- 第一个分割线 -->
        <ResizableDivider divider-type="first" :left-min-width="200" :left-max-width="600" :right-min-width="200"
            :right-max-width="600" @resize="handleFirstDividerResize" />

        <!-- 中间对话区域 -->
        <ChatSidebar :selected-character="currentTool" :selected-session="currentSession" :model-type="modelType"
            :chat-sessions="chatSessions" :pagination="sessionPagination" @selectSession="handleSessionSelect"
            @create-new-chat="handleCreateNewChat" @edit-remark="handleEditRemark" @share-session="handleShareSession"
            @delete-session="handleDeleteSession" @scroll="handleSessionScroll" @filter-change="handleFilterChange" />

        <!-- 第二个分割线 -->
        <ResizableDivider divider-type="second" :left-min-width="200" :left-max-width="600" :right-min-width="200"
            :right-max-width="600" @resize="handleSecondDividerResize" />

        <!-- 右侧工具列表 -->
        <ImageToolMessage ref="imageToolMessageRef" :current-tool="currentTool" :current-session="currentSession"
            :model-type="modelType" :current-model="currentModel" :max-images="maxImages" :user-avatar="userAvatar"
            :ai-avatar="aiAvatar" @model-selected="onModelSelected" @share-session="handleShareSession"
            @show-tool-details="handleShowToolDetails" @session-message-updated="handleSessionMessageUpdated"
            @session-created="handleSessionCreated" @message-update-num="handleMessageUpdateNum" />

        <!-- Create Image Tool Dialog -->
        <CreateImageTool v-model:visible="createDialogVisible" :fill-data="editToolData" @create="handleToolCreated"
            @cancel="handleCreateCancel" />

        <!-- Prompt View -->
        <PromptView v-model:visible="isPromptViewDialogVisible" :prompt="currentPromptData"
            :detail-data="toolDetailData" :loading="isLoadingToolDetail" @delete="handleToolDelete"
            @edit="handleEdit" />

        <!-- Remark Dialog -->
        <RemarkDialog v-model:visible="isRemarkDialogVisible" :session="currentSession" @save="handleRemarkSave" />

        <!-- 删除确认弹窗 -->
        <SessionDeleteDialog v-model:visible="deleteDialogVisible" :session="currentSession"
            @confirm="confirmDeleteSession" />
    </div>
</template>

<script setup>
import { ref, onMounted, onUnmounted, nextTick, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import { ElMessage } from 'element-plus';

import ChatSidebar from '@/components/ai-chat-tool/chat-sidebar.vue';
import CharacterSidebar from '@/components/ai-chat-tool/character-sidebar.vue';
import ResizableDivider from '@/components/business/resizable-divider.vue';
import CreateImageTool from '@/components/ai-chat-tool/create-image-tool.vue';
import PromptView from '@/components/dialog/prompt-view.vue';
import RemarkDialog from '@/components/dialog/remark-dialog.vue';
import SessionDeleteDialog from '@/components/dialog/session-delete-dialog.vue';
import ImageToolMessage from './tool-message.vue';
import { ApiImageTool } from '@/api/api-image-tool';
import { useUserStore } from '@/store/modules/user';

import { MODEL_CAPABILITIES } from '@/models/chat-model-models';
import { useResizablePanels } from '@/composables/useResizablePanels';
import { validateAndSetAIModel } from '@/utils/ai-model-validator';

const { t } = useI18n();
const userStore = useUserStore();
const modelType = MODEL_CAPABILITIES.IMAGE_ANALYSIS

// 使用拖拽面板功能
const {
    leftPanelWidth: toolSidebarWidth,
    rightPanelWidth: chatSidebarWidth,
    pageStyle,
    handleFirstDividerResize,
    handleSecondDividerResize
} = useResizablePanels({
    leftPanel: {
        defaultPercent: 20,
        defaultPixels: 300, // 默认300px宽度
        minPixels: 200,
        maxPixels: 600
    },
    rightPanel: {
        defaultPercent: 20,
        defaultPixels: 300, // 默认300px宽度
        minPixels: 200,
        maxPixels: 600
    },
    storageKey: 'image-tool-panels'
});
// 响应式数据
const currentSession = ref(null);
const currentTool = ref(null);
const currentModel = ref('');
const createDialogVisible = ref(false);
const currentPromptData = ref(null);
const isPromptViewDialogVisible = ref(false);
const toolDetailData = ref(null);
const isLoadingToolDetail = ref(false);
const isRemarkDialogVisible = ref(false);
const editToolData = ref(null);
const deleteDialogVisible = ref(false);
const filterParams = ref({
    model: null,
});
const maxImages = ref(5);

const toolSidebarRef = ref(null);
const imageToolMessageRef = ref(null);

// 头像配置
const userAvatar = '/static/images/default_avatar.png';
const aiAvatar = '/static/images/image_chat/system_avatar_icon.png';

// 新的模型选择事件处理
const onModelSelected = async (modelName) => {    
    // 切换模型时自动创建新会话
    let newSessionIndex = chatSessions.value.findIndex(session => session.isNew);
    if (currentModel.value && modelName && currentModel.value !== modelName) {
        if (newSessionIndex > -1) {
            chatSessions.value[newSessionIndex].ai_model = modelName;
            currentModel.value = modelName;
            if (currentSession.value?.id != chatSessions.value[newSessionIndex].id) {
                currentSession.value = chatSessions.value[newSessionIndex];
            }
            return;
        }

        await handleCreateNewChat(modelName);
    }
    currentModel.value = modelName;
    if (newSessionIndex > -1) {
        chatSessions.value[newSessionIndex].ai_model = currentModel.value;
    }
};

// 处理会话消息更新
const handleSessionMessageUpdated = ({ sessionId, lastMessageContent, lastMessageTime }) => {
    // 更新会话列表中的会话信息
    updateChatSession(sessionId, {
        last_message_content: lastMessageContent,
        last_message_time: lastMessageTime
    });
    
    // 更新当前选中会话的显示
    if (currentSession.value && currentSession.value.id === sessionId) {
        currentSession.value.last_message_content = lastMessageContent;
        currentSession.value.last_message_time = lastMessageTime;
    }
};

// 模拟图片工具数据
const mockImageTools = ref([]);

// 模拟会话数据
const mockSessions = ref([]);

// 会话数据管理
const chatSessions = ref([]);
const sessionPagination = ref({
    cursor: null,
    hasMore: false,
    pageSize: 20,
    loading: false
});

// 加载聊天会话列表
const loadChatSessions = async (isInit = true) => {
    if (!currentTool.value) return;

    try {
        // 设置loading状态
        if (isInit) {
            sessionPagination.value.loading = true;
            sessionPagination.value.cursor = null;
            sessionPagination.value.hasMore = false;
        } else {
            sessionPagination.value.loading = true;
        }

        const response = await ApiImageTool.getImageToolSessions({
            tool_id: currentTool.value.id,
            page_size: sessionPagination.value.pageSize,
            cursor: sessionPagination.value.cursor,
            model: filterParams.value.model || null
        });

        if (response && response.code === 200 && response.data) {
            const newItems = response.data.items || [];

            if (!isInit) {
                // 加载更多时追加数据
                chatSessions.value.push(...newItems);
            } else {
                // 首次加载时替换数据
                chatSessions.value = newItems;
            }

            // 更新分页状态
            sessionPagination.value.hasMore = response.data.has_more || false;

            // 更新cursor为最后一条数据的id
            if (newItems.length > 0) {
                sessionPagination.value.cursor = newItems[newItems.length - 1].id;
            }
        } else {
            throw new Error('API response error');
        }
    } catch (error) {
        console.error('Failed to load chat sessions:', error);

        if (isInit) {
            // 只在首次加载失败时使用模拟数据作为后备
            chatSessions.value = mockSessions.value;
            sessionPagination.value.hasMore = false;
        }

        ElMessage.warning(t('loadError') || 'Failed to load chat sessions');
    } finally {
        if (!isInit) {
            sessionPagination.value.loading = false;
        } else {
            sessionPagination.value.loading = false;
        }
    }
};

// 添加新会话到列表顶部
const addChatSession = (newSession) => {
    chatSessions.value.unshift(newSession);
};

// 从列表中移除会话
const removeChatSession = (sessionId) => {
    const index = chatSessions.value.findIndex(session => session.id === sessionId);
    if (index > -1) {
        chatSessions.value.splice(index, 1);
    }
};

// 更新列表中的会话
const updateChatSession = (sessionId, updates) => {
    const index = chatSessions.value.findIndex(session => session.id === sessionId);
    if (index > -1) {
        chatSessions.value[index] = { ...chatSessions.value[index], ...updates };
    }
};

// 重置会话状态
const resetSessions = () => {
    chatSessions.value = [];
    sessionPagination.value.cursor = null;
    sessionPagination.value.hasMore = false;
    sessionPagination.value.loading = true;
};

// 图片工具数据格式化函数
const formatImageToolItem = (tool) => ({
    id: tool.id,
    title: tool.title || tool.name,
    description: tool.description,
    preview: tool.prompt_preview || tool.prompt,
    author: `${tool.creator_name} ${t('at')} ${formatToolDate(tool.created_at)}`,
    stats: formatUsageCount(tool.usage_count || tool.chat_count),
    creator: tool.creator_name,
    createdAt: tool.created_at,
});

// 工具选择处理
const handleToolSelect = async (formattedTool) => {
    try {
        // 输入验证
        if (!formattedTool || !formattedTool.id) {
            ElMessage.warning(t('invalidToolData'));
            return;
        }
        // 防止重复选择同一个工具
        if (currentTool.value && currentTool.value.id === formattedTool.id) {
            return;
        }
        maxImages.value = toolSidebarRef.value.characters.find(item => item.id === formattedTool.id)?.config?.max_images || 5;

        currentTool.value = formattedTool;
        currentSession.value = null;
        // 重置会话分页状态
        resetSessions();
        try {
            await loadChatSessions(true);
        } catch (error) {
            ElMessage.error(t('loadSessionsError'));
        }
        // 清空组件中的消息
        if (imageToolMessageRef.value) {
            imageToolMessageRef.value.clearMessages();
        }
    } catch (error) {
        ElMessage.error(t('toolSelectionError'));
        // 在发生错误时重置状态
        currentTool.value = null;
        currentSession.value = null;
    }
};

// 会话选择处理
const handleSessionSelect = async (session) => {
    if (currentSession.value?.id === session.id) {
        return;
    }

    currentSession.value = session;
    await validateAndSetAIModel({
        sessionModel: session.ai_model,
        modelType: 'image_analysis',
        currentModelRef: currentModel
    });
};

// 创建新聊天处理
const handleCreateNewChat = async (modelName) => {
    if (!currentTool.value) return;

    const userName = userStore.userInfo?.nickname || '';
    const newSession = {
        id: String(Date.now()), // 确保ID是字符串类型
        title: userName,
        user_name: userName,
        last_message_content: '',
        last_message_time: new Date().toISOString(),
        remark: '',
        is_pinned: false,
        message_count: 0,
        isNew: true
    };
    if (modelName) {
        newSession.ai_model = modelName;
        currentModel.value = modelName;
    }
    
    addChatSession(newSession);
    currentSession.value = newSession;
    ElMessage.success(t('chatCreated'));
};


// 编辑备注处理
const handleEditRemark = (session) => {
    isRemarkDialogVisible.value = true;
    currentSession.value = session;
};

// 删除会话处理
const handleDeleteSession = (session) => {
    deleteDialogVisible.value = true;
    currentSession.value = session;
};

// 会话滚动处理
const handleSessionScroll = (event) => {
    if (currentTool.value) {
        const { scrollTop, scrollHeight, clientHeight } = event.target;
        const threshold = 50;

        if (scrollHeight - scrollTop - clientHeight < threshold &&
            sessionPagination.value.hasMore &&
            !sessionPagination.value.loading) {
            loadChatSessions(true);
        }
    }
};

// 创建工具处理
const handleCreateTool = () => {
    createDialogVisible.value = true;
};

// 处理工具创建成功
const handleToolCreated = () => {
    ElMessage.success(t('toolCreated'));
    createDialogVisible.value = false;

    // 重新加载工具列表
    if (toolSidebarRef.value) {
        toolSidebarRef.value.loadCharacters();
    }
};

// 处理创建取消
const handleCreateCancel = () => {
    createDialogVisible.value = false;
};

// 处理工具删除
const handleToolDelete = async (toolData) => {
    try {
        const response = await ApiImageTool.deleteImageTool({
            tool_id: toolData.id
        });
        
        if (response && response.code === 200) {
            ElMessage.success(t('toolDeleted'));
            if (toolSidebarRef.value) {
                toolSidebarRef.value.loadCharacters();
            }
            
            // 如果删除的是当前选中的工具，清除选中状态
            if (currentTool.value?.id === toolData.id) {
                currentTool.value = null;
                currentSession.value = null;
            }
            
            // 关闭弹窗
            isPromptViewDialogVisible.value = false;
        } else {
            throw new Error('API response error');
        }
    } catch (error) {
        console.error('Failed to delete tool:', error);
        ElMessage.error(t('deleteError'));
    }
};

// 显示角色详情（右上角按钮）
const handleShowToolDetails = (item) => {
    if (item && (item.id || currentTool.value)) {
        const tool = item.id ? item : currentTool.value;
        currentPromptData.value = {
            id: tool.id,
            content: tool.preview,
            category: tool.title,
            description: tool.description,
            creator: tool.creator,
            createdAt: tool.createdAt,
            chats: tool.stats
        };
        
        // 重置详情数据状态
        toolDetailData.value = null;
        isLoadingToolDetail.value = false;
        isPromptViewDialogVisible.value = true;
    }
};

// 分享聊天
const handleShareSession = () => {
    ElMessage.info(t('shareFeatureComingSoon'));
};

// 处理临时会话创建更新数据
const handleSessionCreated = async (sessionData) => {
    try {
        // 检查是否是临时新会话
        if (currentSession.value.isNew) {
            await loadChatSessions(true);
            if (chatSessions.value.length > 0) {
                currentSession.value.id = chatSessions.value[0]?.id;
            }
        }
    } catch (error) {
        console.error('Failed to handle session creation:', error);
    }
};

const handleMessageUpdateNum = (messageData) => {
    const { sessionId, num } = messageData;
    const index = chatSessions.value.findIndex(session => session.id === sessionId);
    let count = 0;
    if(index > -1) {
        count = chatSessions.value[index].message_count;
    }
    chatSessions.value[index].message_count = count + num;
};

// 工具函数
const formatToolDate = (dateString) => {
    if (!dateString) return '';
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { month: '2-digit', day: '2-digit', year: 'numeric' }) +
           ' ' + date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
};

const formatUsageCount = (count) => {
    if (!count) return '0';
    if (count >= 1000) {
        return (count / 1000).toFixed(1) + 'k';
    }
    return count.toString();
};

// 处理删除确认
const confirmDeleteSession = () => {
    deleteSession(currentSession.value.id);
    deleteDialogVisible.value = false;
};

// 监听创建弹窗状态变化，弹窗关闭时清除快速填写数据
watch(() => createDialogVisible.value, (isVisible) => {
    if (!isVisible) {
        editToolData.value = null;
    }
});

// 处理删除会话
const deleteSession = async (sessionId) => {
    try {
        const response = await ApiImageTool.deleteImageToolSession(String(sessionId));
        if (response && response.code === 200) {
            ElMessage.success(t('sessionDeleted'));
            removeChatSession(sessionId);
            if (currentSession.value?.id === sessionId) {
                currentSession.value = null;
            }
        } else {
            throw new Error('API response error');
        }
    } catch (error) {
        ElMessage.error(t('deleteError'));
    }
};

// 处理过滤变化
const handleFilterChange = (params) => {
    filterParams.value.model = params.modelName;
    if (currentTool.value) {
        loadChatSessions(true);
    }
};


// 处理快速填写（编辑功能）
const handleEdit = (toolData) => {
    try {
        // 如果toolData有tool属性，说明是来自PromptView的数据结构
        let tool;
        if (toolData.tool) {
            tool = {
                ...toolData.tool,
                creator_name: toolData.creator_name,
                max_images: toolData?.tool?.config?.max_images || 1
            };
        } else {
            // 否则使用原有的数据结构
            tool = toolData;
        }
        
        // 使用传入的数据
        editToolData.value = {
            id: tool.id,
            title: tool.category,
            description: tool.description,
            prompt: tool.prompt || tool.content || tool.preview || '',
            max_images: tool.max_images || tool.maxImages || 1,
        };
        isPromptViewDialogVisible.value = false;
        // 打开创建弹窗
        createDialogVisible.value = true;
    } catch (error) {
        ElMessage.error(t('loadEditDataFailed') || 'Failed to load data for quick fill');
    }
};

// 处理备注保存
const handleRemarkSave = async (remark) => {
    if (!currentSession.value) return;
    
    try {
        // 调用API更新备注
        const response = await ApiImageTool.updateImageToolSessionRemark(String(currentSession.value.id), remark);
        
        if (response && response.code === 200) {
            // 1. 更新会话数组中的会话数据
            updateChatSession(currentSession.value.id, { remark });
            
            // 2. 同时更新当前选中会话的备注显示
            currentSession.value.remark = remark;
            // 显示成功提示
            ElMessage.success(t('remarkUpdated'));
        } else {
            throw new Error('API response error');
        }
    } catch (error) {
        console.error('Failed to update remark:', error);
        ElMessage.error(t('updateError') || 'Failed to update remark');
    }
};

// 生命周期钩子函数
onMounted(() => {
    // 初始化逻辑
});

onUnmounted(() => {
    // 清理资源
});
</script>

<style scoped lang="scss">
.image-tool-page {
    display: flex;
    width: 100%;
    height: var(--height-small-base-view);
    background: var(--bg-secondary);
    box-sizing: border-box;
    overflow: hidden;
}
</style>