<template>
    <div class="image-tool-message" ref="messageMainRef">
        <!-- 空状态页面 -->
        <div v-if="!currentSession || !currentTool" class="empty-state">
            <p class="empty-text">{{ t('selectChatToStart') }}</p>
        </div>

        <!-- 聊天内容区域 -->
        <template v-else>
            <!-- 聊天头部 -->
            <SessionHeader :session="sessionForHeader" :character="currentTool" :format-date-only="formatDateOnly"
                @share="handleShareSession" @show-details="handleShowToolDetails" />

            <!-- 消息内容区域 -->
            <div v-loading="showMessageAreaLoading" class="chat-content-container">
                <div ref="chatContentRef" @scroll="handleScroll" class="chat-content">
                    <!-- 加载更多提示（顶部） -->
                    <div v-if="loadingType === 'more'" class="loading-more">
                        <div class="loading-spinner"></div>
                        <span>{{ t("loading") }}</span>
                    </div>

                    <!-- 消息列表 -->
                    <div v-for="item in messageList" :key="item.id" class="message-item"
                        :class="{ 'message-user': item.role === MSG_ROLE_USER }">
                        <!-- 用户消息 -->
                        <div v-if="item.role === MSG_ROLE_USER" class="user-message">
                            <div class="message-content">
                                <!-- 用户发送的图片 -->
                                <div v-if="item.type === 'image' && item.images?.length > 0" class="image-grid">
                                    <l-img v-for="(image, imgIndex) in item.images" :key="imgIndex"
                                        :previewList="item.images" :previewIndex="imgIndex" :src="image.url || image"
                                        w="150px" h="150px" radius="6px" border="1px solid #E5E7EB" />
                                </div>
                                <div v-else-if="item.content && !item.type" class="image-grid">
                                    <l-img v-for="(image, imgIndex) in item.content" :key="imgIndex"
                                        :previewList="item.content" :previewIndex="imgIndex" :src="image.url || image"
                                        w="150px" h="150px" radius="6px" border="1px solid #E5E7EB" />
                                </div>
                                <div class="message-time">{{ formatTime(item, item.role) }}</div>
                            </div>
                            <div class="user-avatar">
                                <l-img :src="userAvatar" w="32px" h="32px" radius="16px" fit="cover" />
                            </div>
                        </div>

                        <!-- AI消息 -->
                        <div v-else class="assistant-message">
                            <div class="assistant-avatar">
                                <l-img :src="aiAvatar" w="32px" h="32px" radius="16px" fit="cover" />
                            </div>
                            <div class="message-content">
                                <msg-item-text :content="item.content" :role="item.role" :isMarkdown="item.isMarkdown"
                                    :typing="item.typing" :showLoading="item.showLoading" theme="text-tool"
                                    @onFinish="handleMessageFinish(item.id)">
                                    <template #footer>
                                        <div class="message-time assistant-time">{{ formatTime(item, item.role) }}</div>
                                    </template>
                                </msg-item-text>
                            </div>
                        </div>
                    </div>

                    <!-- 底部占位符，用于滚动定位 -->
                    <div ref="lastMsgRef" class="last-msg-ref-full-width"></div>
                </div>

                <!-- 输入区域 -->
                <div v-if="currentModel" class="chat-input">
                    <div class="input-container">
                        <div v-if="uploadedImages.length > 0" class="uploaded-images">
                            <div v-for="(image, index) in uploadedImages" :key="image.id || index"
                                class="uploaded-image">
                                <l-img v-if="!image.isLoading" :src="image.url || image.preview" w="50px" h="50px"
                                    :previewList="uploadedImages" :previewIndex="index" radius="4px"
                                    border="1px solid #E5E7EB" />
                                <div v-else class="loading-container">
                                    <!-- 显示本地预览图片作为背景 -->
                                    <l-img :src="image.preview" w="50px" h="50px" radius="4px"
                                        border="1px solid #E5E7EB" class="preview-background" />
                                    <!-- 加载动画覆盖层 -->
                                    <div class="loading-overlay">
                                        <img src="/static/images/file_loading.png" class="loading-icon" />
                                    </div>
                                </div>
                                <button class="remove-image" @click="removeImage(index)">
                                    <l-img :src="'/static/images/close_icon.png'" w="12px" h="12px" />
                                </button>
                            </div>
                        </div>
                        <div class="input-tip">{{ t('uploadLimit', { count: maxImages }) }}</div>
                    </div>

                    <div class="input-actions">
                        <div class="upload-section">
                            <input ref="fileInputRef" type="file" multiple accept="image/jpeg,image/jpg,image/png"
                                style="display: none" @change="onFileSelect" />
                            <button class="upload-btn" @click="triggerFileSelect">
                                <l-img :src="'/static/images/image_chat/upload_file_icon.png'" w="16px" h="16px" />
                            </button>
                        </div>

                        <div class="input-content">
                            <div class="model-selector">
                                <l-dropdown :type="modelType" ref="modelDropdownRef" :initialSelected="currentModel" @update:selected="onModelSelected"
                                    trigger="click">
                                    <div class="model-display">
                                        <span>{{ currentModel }}</span>
                                    </div>
                                </l-dropdown>
                            </div>
                            <l-send-button :isCanSend="canSendMessage" :isLoading="isAnalyzing"
                                @onClickSend="handleSendMessage" @onClickStop="handleStopAnalysis" />
                        </div>
                    </div>
                </div>

                <!-- 拖拽遮罩层 -->
                <div v-if="isDragOver" class="drag-overlay">
                    <div class="drag-content">
                        <l-img :src="'/static/images/image_chat/upload_file_icon.png'" w="48px" h="48px" />
                        <h3>{{ t('dropImagesHere') }}</h3>
                        <p>{{ t('supportedFormats') }}</p>
                    </div>
                </div>

                <!-- 粘贴提示 -->
                <div v-if="showPasteHint" class="paste-hint">
                    <l-img :src="'/static/images/image_chat/upload_file_icon.png'" w="24px" h="24px" />
                    <span>{{ t('imagesPastedSuccessfully') }}</span>
                </div>
            </div>
        </template>
    </div>
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted, nextTick, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import { ElMessage } from 'element-plus';
import LImg from '@/components/l-img.vue';
import LDropdown from '@/components/l-dropdown.vue';
import LSendButton from '@/components/l-send-button.vue';
import MsgItemText from '@/views/alien/components/msg-item-text.vue';
import SessionHeader from '@/components/ai-chat-tool/session-header.vue';
import { ALLOWED_FILE_TYPES } from '@/types/upload.ts';
import { pxToRem } from '@/utils/px-to-rem';
import { uploadImage } from '@/api/upload/upload-service';
import { getImageDimensions } from '@/utils/util';
import { MSG_ROLE_USER, MSG_ROLE_ASSISTANT, onSendParseMsg, onAIParseMsg } from '@/types/msg.ts';
import { useSmoothScroll } from '@/utils/util';
import { ApiImageTool } from '@/api/api-image-tool';

const { t } = useI18n();
const { smoothScrollToRef } = useSmoothScroll();

// Props 定义
const props = defineProps({
    // 当前选中的工具
    currentTool: {
        type: Object,
        default: null
    },
    // 当前选中的会话
    currentSession: {
        type: Object,
        default: null
    },
    // messageList 现在由组件内部管理
    // 模型类型
    modelType: {
        type: String,
        required: true
    },
    // 当前模型
    currentModel: {
        type: String,
        default: ''
    },
    // 最大图片数量
    maxImages: {
        type: Number,
        default: 5
    },
    // 用户头像
    userAvatar: {
        type: String,
        default: '/static/images/default_avatar.png'
    },
    // AI头像
    aiAvatar: {
        type: String,
        default: '/static/images/image_chat/system_avatar_icon.png'
    },
});

// Emits 定义
const emit = defineEmits([
    'send-message',           // 发送消息
    'stop-analysis',          // 停止分析
    'model-selected',         // 模型选择
    'share-session',          // 分享会话
    'show-tool-details',      // 显示工具详情
    'scroll',                 // 滚动事件
    'load-more-messages',      // 加载更多消息
    'session-message-updated', // 会话消息更新
    'session-created',         // 新会话创建
    'message-update-num'       // 消息更新数量
]);

// 响应式数据
const uploadedImages = ref([]);
const messageList = ref([]);
const isDragOver = ref(false);
const showPasteHint = ref(false);
const lastScrollTop = ref(0);
const modelDropdownRef = ref(null);

// 消息加载相关状态
const isAnalyzing = ref(false);
const loadingMessages = ref(false);
const loadingType = ref('none'); // 'none' | 'initial' | 'more'
const hasMoreMessages = ref(true);
const messagesCursor = ref(null);
const autoScroll = ref(true);
const streamConnection = ref(null);
const requestCompleted = ref(false);
const isStreamingScroll = ref(false); // 标记是否为流式回复中的滚动
const scrollThrottleTimer = ref(null); // 滚动节流定时器

const messageMainRef = ref(null);
const chatContentRef = ref(null);
const lastMsgRef = ref(null);
const fileInputRef = ref(null);

// 计算属性
const canSendMessage = computed(() => uploadedImages.value.length > 0);

const showMessageAreaLoading = computed(() => {
    return !props.currentSession?.isNew && loadingType.value === 'initial';
});

// 为SessionHeader组件准备的会话数据
const sessionForHeader = computed(() => {
    if (!props.currentSession || !props.currentTool) return null;

    return {
        title: `${props.currentTool.title} - ${t('chatWithName', { name: props.currentSession.user_name || '' })}`,
        last_message_time: new Date().toISOString(), // 使用当前时间作为开始时间
        remark: props.currentSession.remark
    };
});

// 文件选择
const triggerFileSelect = () => {
    // 检查是否已选择工具和会话
    if (!props.currentTool || !props.currentSession) {
        if (!props.currentTool) {
            ElMessage.warning(t('selectToolToStart'));
        } else {
            ElMessage.warning(t('selectChatToStart'));
        }
        return;
    }
    fileInputRef.value?.click();
};

const onFileSelect = (event) => {
    // 检查是否已选择工具和会话
    if (!props.currentTool || !props.currentSession) {
        event.target.value = ''; // 清空文件选择
        return;
    }

    const files = Array.from(event.target.files);
    handleFiles(files);

    // 重要：清空input的value，确保下次选择相同文件时也能触发change事件
    event.target.value = '';
};

// 处理文件上传
const handleFiles = async (files) => {
    // 检查是否已选择工具和会话
    if (!props.currentTool || !props.currentSession) {
        if (!props.currentTool) {
            ElMessage.warning(t('selectToolToStart'));
        } else {
            ElMessage.warning(t('selectChatToStart'));
        }
        return;
    }

    if (uploadedImages.value.length + files.length > props.maxImages) {
        ElMessage.error(t('maxImagesExceeded', { count: props.maxImages }));
        return;
    }

    for (const file of files) {
        // 只允许JPG和PNG格式
        if (!ALLOWED_FILE_TYPES.IMAGE.includes(file.type.toLowerCase())) {
            ElMessage.error(t('unsupportedImageFormat', { format: file.type }));
            continue;
        }

        if (file.size > 10 * 1024 * 1024) {
            ElMessage.error(t('fileSizeExceeded'));
            continue;
        }

        // 创建预览
        const preview = URL.createObjectURL(file);
        const imageData = {
            id: Date.now() + Math.random(), // 添加唯一ID
            file,
            preview,
            isLoading: true, // 添加加载状态
            uploaded: false,
            url: null
        };

        uploadedImages.value.push(imageData);
        // 上传文件
        await realImageUpload(imageData);
    }
};

// 真实图片上传过程
const realImageUpload = async (imageData) => {
    try {
        const dimensions = await getImageDimensions(imageData.preview);
        const uploadResult = await uploadImage(imageData.file, true, dimensions);
        // 找到对应的图片对象并更新状态
        const index = uploadedImages.value.findIndex(img => img.id === imageData.id);
        if (index !== -1) {
            uploadedImages.value[index].isLoading = false;
            uploadedImages.value[index].uploaded = true;
            uploadedImages.value[index].url = uploadResult.url;
            uploadedImages.value[index].mediaId = uploadResult.mediaId;
        }
    } catch (error) {
        // 上传失败，移除图片
        const index = uploadedImages.value.findIndex(img => img.id === imageData.id);
        if (index !== -1) {
            // 释放预览URL
            if (uploadedImages.value[index].preview) {
                URL.revokeObjectURL(uploadedImages.value[index].preview);
            }
            uploadedImages.value.splice(index, 1);
        }

        ElMessage.error(t('imageUploadError'));
    }
};

// 移除图片
const removeImage = (index) => {
    const image = uploadedImages.value[index];
    if (image.preview) {
        URL.revokeObjectURL(image.preview);
    }
    uploadedImages.value.splice(index, 1);
};

// 更新当前会话的最后一条消息内容
const updateCurrentSessionMessage = (messageContent, messageTime) => {
    if (!props.currentSession) return;

    // 截断过长的消息内容
    const truncatedMessage = messageContent.length > 100
        ? messageContent.substring(0, 100) + '...'
        : messageContent;

    emit('session-message-updated', {
        sessionId: props.currentSession.id,
        lastMessageContent: truncatedMessage,
        lastMessageTime: messageTime
    });
};

// 发送消息 - 完整的内部处理
const sendStreamMessage = async () => {
    if (!uploadedImages.value.length || isAnalyzing.value || !props.currentTool) return;

    // 先关闭之前的连接（如果存在）
    if (streamConnection.value) {
        streamConnection.value.close();
        streamConnection.value = null;
    }

    // 用于累积完整的响应
    let fullResponse = "";

    try {
        isAnalyzing.value = true;
        isStreamingScroll.value = true; // 开始流式回复
        // 添加用户消息到界面
        const currentTime = new Date().toISOString();
        const userMessageData = {
            id: `user_${Date.now()}`,
            role: MSG_ROLE_USER,
            type: 'image',
            images: uploadedImages.value.map(img => ({ url: img.url })),
            created_at: currentTime,
            message_type: MSG_ROLE_USER,
        };
        const userMessage = onSendParseMsg(userMessageData);
        // 手动添加时间字段和图片类型
        userMessage.createTime = currentTime;
        userMessage.created_at = currentTime;
        userMessage.type = 'image';
        userMessage.images = uploadedImages.value.map(img => ({ url: img.url }));
        messageList.value.push(userMessage);

        // 更新当前会话的最后一条消息内容（用户消息）
        const userMessageContent = t('imageAnalysisRequest'); // 显示图片分析请求而不是具体图片内容
        updateCurrentSessionMessage(userMessageContent, currentTime);
        emit('message-update-num', {
            sessionId: props.currentSession.id,
            num: 1
        });

        // 添加AI消息占位符
        const aiMessageId = `ai_${Date.now()}`;
        const aiMessageData = {
            id: aiMessageId,
            role: MSG_ROLE_ASSISTANT,
            content: "",
            created_at: currentTime,
            message_type: MSG_ROLE_ASSISTANT,
        };
        const aiMessage = onAIParseMsg(aiMessageData, true);
        // 手动设置typing属性
        aiMessage.typing = { step: 6, interval: 50 };
        // 手动添加时间字段
        aiMessage.createTime = currentTime;
        aiMessage.created_at = currentTime;
        messageList.value.push(aiMessage);

        // 启用自动滚动并滚动到底部
        autoScroll.value = true;
        await nextTick();
        scrollToBottom();

        const imageIds = uploadedImages.value.map(img => img.mediaId);
        const requestParams = {
            tool_id: props.currentTool.id,
            session_id: props.currentSession.id.length != 13 ? String(props.currentSession.id) : null,
            image_ids: imageIds,
            content: '', // 添加content字段，即使为空也要提供
            model: props.currentModel // 添加model字段，必填参数
        };

        streamConnection.value = ApiImageTool.streamImageChat(
            requestParams,
            (streamData) => {
                // 处理流式消息片段
                const aiMessageIndex = messageList.value.findIndex(
                    (msg) => msg.id === aiMessageId
                );
                if (aiMessageIndex !== -1) {
                    const currentMessage = messageList.value[aiMessageIndex];
                    const newContent = streamData.content || "";
                    fullResponse += newContent;
                    const updatedMessage = {
                        ...currentMessage,
                        content: fullResponse,
                        typing: {
                            step:6,
                        },
                        showLoading: false,
                        createTime: currentMessage.createTime,
                        created_at: currentMessage.created_at,
                    };
                    messageList.value[aiMessageIndex] = updatedMessage;

                    // 更新当前会话的最后一条消息内容（AI消息）
                    const truncatedContent = fullResponse.length > 100
                        ? fullResponse.substring(0, 100) + '...'
                        : fullResponse;
                    updateCurrentSessionMessage(truncatedContent, currentTime);

                    // 流式回复时使用节流滚动，避免频繁抖动
                    throttledStreamScroll();
                }
            },
            (error) => {
                // 处理错误
                // 弹出错误提示
                ElMessage.error(t("failedToSendMessage"));

                // 删除失败的AI消息
                messageList.value = messageList.value.filter(
                    (msg) => msg.id !== aiMessageId
                );

                // 设置请求完成状态
                requestCompleted.value = true;
                isAnalyzing.value = false; // 错误时直接重置发送按钮状态
                isStreamingScroll.value = false; // 重置流式状态

                // 清除连接引用
                streamConnection.value = null;
            },
            () => {
                requestCompleted.value = true;
                streamConnection.value = null;
                isStreamingScroll.value = false; // 结束流式回复

                // 流式回复结束后，最后滚动到底部（可以使用平滑动画）
                if (autoScroll.value) {
                    nextTick(() => {
                        scrollToBottom(200, false); // 使用短动画
                    });
                }
                emit('message-update-num', {
                    sessionId: props.currentSession.id,
                    num: 1
                });

                // 通知父组件会话已创建
                emit('session-created', {
                    sessionId : props.currentSession.tool_id,
                });
            }
        );

        // 清空上传的图片
        uploadedImages.value.forEach(img => {
            if (img.preview) URL.revokeObjectURL(img.preview);
        });
        uploadedImages.value = [];
    } catch (error) {
        ElMessage.error(t('analysisError'));
    } finally {
        scrollToBottom();
    }
};

// 发送消息的对外接口
const handleSendMessage = () => {
    if (!canSendMessage.value || isAnalyzing.value || !props.currentTool) return;

    const unuploadedImages = uploadedImages.value.filter(img => img.isLoading);
    if (unuploadedImages.length > 0) {
        ElMessage.warning(t('processingImage'));
        return;
    }

    sendStreamMessage();
};

// 停止分析
const handleStopAnalysis = () => {
    if (streamConnection.value) {
        streamConnection.value.close();
        streamConnection.value = null;
    }

    // 设置请求完成状态为true，以便onFinish可以处理
    requestCompleted.value = true;
    isStreamingScroll.value = false; // 重置流式状态

    // 由于主动停止，可以直接修改发送按钮状态
    isAnalyzing.value = false;

    emit('stop-analysis');
};

// 模型选择事件处理
const onModelSelected = (modelName) => {
    emit('model-selected', modelName);
};

// 分享会话
const handleShareSession = () => {
    emit('share-session');
};

// 显示工具详情
const handleShowToolDetails = () => {
    emit('show-tool-details',props.currentTool);
};

// 消息完成回调
const handleMessageFinish = (messageId) => {
    if (!requestCompleted.value) {
        return;
    }

    const finishedMessage = messageList.value.find(msg => msg.id === messageId);
    if (finishedMessage && finishedMessage.role === MSG_ROLE_ASSISTANT) {
        const messageIndex = messageList.value.findIndex(msg => msg.id === messageId);
        if (messageIndex !== -1) {
            isAnalyzing.value = false;
        }
    }
};

// 滚动处理
const handleScroll = (e) => {
    const el = e.target;
    const currentScrollTop = el.scrollTop;
    const scrollHeight = el.scrollHeight;
    const clientHeight = el.clientHeight;

    // 计算滚动方向
    const isScrollingUp = currentScrollTop < lastScrollTop.value;

    // 判断是否滚动到底部（允许5px的误差）
    const isAtBottom = scrollHeight - (currentScrollTop + clientHeight) < 5;

    // 如果用户滚动到底部，恢复自动滚动
    if (isAtBottom) {
        autoScroll.value = true;
    }
    // 如果用户向上滚动，关闭自动滚动
    else if (isScrollingUp) {
        autoScroll.value = false;
    }

    // 检查是否向上滚动且接近顶部，加载更多消息
    const SCROLL_THRESHOLD = 50;
    if (
        isScrollingUp &&
        currentScrollTop <= SCROLL_THRESHOLD &&
        !loadingMessages.value &&
        hasMoreMessages.value
    ) {
        loadSessionMessages(false);
    }

    // 发送滚动事件给父组件
    emit('scroll', {
        isScrollingUp,
        isAtBottom,
        scrollTop: currentScrollTop,
        scrollHeight,
        clientHeight
    });

    // 更新上次滚动位置
    if (!loadingMessages.value) {
        lastScrollTop.value = currentScrollTop;
    }
};

// 滚动到底部
const scrollToBottom = async (duration = 300, isStreaming = false) => {
    if (!autoScroll.value) return;

    await nextTick();
    if (!chatContentRef.value) return;

    // 备用滚动方法：直接设置scrollTop
    const scrollToBottomDirect = () => {
        if (chatContentRef.value && autoScroll.value) {
            const maxScrollTop = chatContentRef.value.scrollHeight - chatContentRef.value.clientHeight;
            chatContentRef.value.scrollTop = Math.max(0, maxScrollTop);
        }
    };

    if (isStreaming) {
        // 流式回复时使用直接滚动，避免动画抖动
        scrollToBottomDirect();
    } else {
        // 非流式回复时可以使用平滑滚动
        // 如果有lastMsgRef，优先使用平滑滚动
        if (lastMsgRef.value && duration > 0) {
            smoothScrollToRef(lastMsgRef, {
                container: chatContentRef.value,
                duration: duration,
                offset: 20,
                easing: "easeOutQuad",
            });
        }

        // 立即尝试一次直接滚动
        scrollToBottomDirect();

        // 延迟后再次尝试（给DOM更多时间完成渲染）
        setTimeout(scrollToBottomDirect, duration > 0 ? duration + 50 : 50);
    }
};

// 节流的流式滚动方法
const throttledStreamScroll = () => {
    if (scrollThrottleTimer.value) {
        return; // 如果已有pending的滚动，直接返回
    }

    scrollThrottleTimer.value = setTimeout(() => {
        if (autoScroll.value) {
            scrollToBottom(0, true); // 流式滚动：无动画，直接滚动
        }
        scrollThrottleTimer.value = null;
    }, 100); // 100ms节流，减少滚动频率
};

const formatDateOnly = (dateString) => {
    if (!dateString) return '';
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { month: '2-digit', day: '2-digit', year: 'numeric' });
};

// 通用消息格式化函数
const formatApiMessage = (apiMessage, isHistoryMessage = true) => {
    // 安全解析用户消息内容
    let content = apiMessage.content;
    if (apiMessage.message_type === MSG_ROLE_USER) {
        try {
            content = JSON.parse(apiMessage.content);
        } catch (error) {
            // 如果解析失败，直接使用原始内容
            console.warn('Failed to parse user message content as JSON:', error.message);
            content = apiMessage.content;
        }
    }
    const baseMessage = {
        id: apiMessage.id,
        role: apiMessage.message_type,
        content: content,
        created_at: apiMessage.created_at,
        createTime: apiMessage.created_at,
        message_type: apiMessage.message_type,
        typing: false,
        showLoading: false,
        isMarkdown: apiMessage.message_type === MSG_ROLE_ASSISTANT
    };

    // 如果是用户消息且包含图片
    if (apiMessage.message_type === MSG_ROLE_USER && apiMessage.images && apiMessage.images.length > 0) {
        baseMessage.type = 'image';
        baseMessage.images = apiMessage.images.map(img => ({
            url: img.url,
            width: img.width,
            height: img.height,
            size: img.size
        }));
    }

    // 根据消息类型使用对应的解析函数
    if (apiMessage.message_type === MSG_ROLE_USER) {
        return onSendParseMsg(baseMessage);
    } else {
        // 对于历史消息，typing 设为 false
        return onAIParseMsg(baseMessage, !isHistoryMessage ? {step:6} : false);
    }
};

// 加载会话消息（统一方法，支持初始加载和加载更多）
const loadSessionMessages = async (isInitial = true) => {
    if (!props.currentSession?.id) {
        console.warn('Current session is required to load messages');
        return;
    }

    // 防止重复加载
    if (!isInitial && (loadingMessages.value || !hasMoreMessages.value)) {
        return;
    }

    try {
        // 设置加载状态
        if (isInitial) {
            loadingType.value = 'initial';
            messagesCursor.value = null;
            hasMoreMessages.value = true;
        } else {
            loadingType.value = 'more';
        }
        loadingMessages.value = true;

        // 调用API获取消息列表
        const response = await ApiImageTool.getImageToolMessages({
            session_id: props.currentSession.id,
            page_size: 20,
            cursor: isInitial ? null : messagesCursor.value
        });

        if (response.code && response.code == 200) {
            const { items, has_more } = response.data;

            if (items.length > 0) {
                // 转换API消息格式为组件需要的格式
                const formattedMessages = items.map(apiMessage => {
                    return formatApiMessage(apiMessage, true);
                });

                if (isInitial) {
                    // 初始加载：由于API返回的是按创建时间降序排序（最新的在前），需要反转数组以显示正确的时间顺序
                    messageList.value = formattedMessages.reverse();

                    // 滚动到底部显示最新消息
                    autoScroll.value = true;
                    await nextTick();

                    // 多次尝试滚动，确保DOM完全渲染后能正确滚动到底部
                    scrollToBottom(0); // 立即滚动，不需要动画

                    // 延迟再次滚动，确保所有消息组件都已渲染完成
                    setTimeout(() => {
                        scrollToBottom(0);
                    }, 100);

                    // 最后一次保险滚动
                    setTimeout(() => {
                        scrollToBottom(0);
                    }, 300);
                } else {
                    // 加载更多：处理滚动位置
                    const scrollContainer = chatContentRef.value;
                    const oldScrollHeight = scrollContainer.scrollHeight;
                    const oldScrollTop = scrollContainer.scrollTop;

                    // 由于API返回的是按创建时间降序排序，需要反转后添加到消息列表前面
                    const reversedMessages = formattedMessages.reverse();
                    messageList.value = [...reversedMessages, ...messageList.value];

                    // 恢复滚动位置，保持用户当前查看的内容不变
                    await nextTick();
                    const newScrollHeight = scrollContainer.scrollHeight;
                    const scrollDiff = newScrollHeight - oldScrollHeight;
                    scrollContainer.scrollTop = oldScrollTop + scrollDiff;

                    // 暂时禁用自动滚动，因为用户正在查看历史消息
                    autoScroll.value = false;
                }

                // 更新分页状态
                hasMoreMessages.value = has_more;
                // 设置游标为最早的消息ID（用于加载更多历史消息）
                messagesCursor.value = items[items.length - 1].id;
            }

        } else {
            if (isInitial) {
                ElMessage.error(t('sessionLoadError'));
            }
        }

    } catch (error) {
        if (isInitial) {
            ElMessage.error(t('sessionLoadError'));
        }
    } finally {
        loadingMessages.value = false;
        loadingType.value = 'none'; // 重置加载类型
    }
};

// 时间格式化
const formatTime = (item, role) => {
    if (!item) return "";

    // 从消息对象中获取时间字段
    const timeStr = item.createTime || item.created_at;
    if (!timeStr) return "";

    const date = new Date(timeStr);

    if (role === MSG_ROLE_USER) {
        // 用户消息格式：05/07, 2025 10:23
        const month = String(date.getMonth() + 1).padStart(2, "0");
        const day = String(date.getDate()).padStart(2, "0");
        const year = date.getFullYear();
        const hours = String(date.getHours()).padStart(2, "0");
        const minutes = String(date.getMinutes()).padStart(2, "0");

        return `${month}/${day}, ${year} ${hours}:${minutes}`;
    } else {
        // AI消息格式：May 8, 2025 10:24
        return (
            date.toLocaleDateString("en-US", {
                month: "long",
                day: "numeric",
                year: "numeric",
            }) +
            " " +
            date.toLocaleTimeString("en-US", {
                hour: "2-digit",
                minute: "2-digit",
                hour12: false,
            })
        );
    }
};

// 拖拽事件处理
const handleDragEnter = (e) => {
    // 检查是否已选择工具和会话
    if (!props.currentTool || !props.currentSession) {
        return;
    }

    e.preventDefault();
    e.stopPropagation();
    isDragOver.value = true;
};

const handleDragOver = (e) => {
    // 检查是否已选择工具和会话
    if (!props.currentTool || !props.currentSession) {
        return;
    }

    e.preventDefault();
    e.stopPropagation();
};

const handleDragLeave = (e) => {
    // 检查是否已选择工具和会话
    if (!props.currentTool || !props.currentSession) {
        return;
    }

    e.preventDefault();
    e.stopPropagation();

    // 检查是否真的离开了拖拽区域
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX;
    const y = e.clientY;

    if (x < rect.left || x > rect.right || y < rect.top || y > rect.bottom) {
        isDragOver.value = false;
    }
};

const handleDrop = (e) => {
    // 检查是否已选择工具和会话
    if (!props.currentTool || !props.currentSession) {
        e.preventDefault();
        e.stopPropagation();
        return;
    }

    e.preventDefault();
    e.stopPropagation();
    isDragOver.value = false;

    const files = Array.from(e.dataTransfer.files);
    // 只允许JPG和PNG格式
    const imageFiles = files.filter(file => ALLOWED_FILE_TYPES.IMAGE.includes(file.type.toLowerCase()));

    if (imageFiles.length > 0 && uploadedImages.value.length + imageFiles.length <= props.maxImages) {
        handleFiles(imageFiles);
    } else if (files.length > 0) {
        ElMessage.error(t('maxImagesExceeded', { count: props.maxImages }));
    }
};

// 粘贴事件处理
const handlePaste = (e) => {
    // 检查是否已选择工具和会话
    if (!props.currentTool || !props.currentSession) {
        return;
    }

    const items = e.clipboardData?.items;
    if (!items) return;

    const files = [];
    for (let i = 0; i < items.length; i++) {
        const item = items[i];
        if (item.type.startsWith('image/')) {
            const file = item.getAsFile();
            if (file) files.push(file);
        }
    }

    if (files.length > 0) {
        if (files.length + uploadedImages.value.length > props.maxImages) {
            ElMessage.error(t('maxImagesExceeded', { count: props.maxImages }));
            return;
        }
        // 显示粘贴成功提示
        showPasteHint.value = true;
        setTimeout(() => {
            showPasteHint.value = false;
        }, 2000);
        handleFiles(files);
    }
};

watch(() => props.currentSession?.id, async (newSessionId) => {
    if (newSessionId && newSessionId.length != 13) {
        if (!props.currentSession.isNew) {
            loadSessionMessages(true);
        }
    } else {
        messageList.value = [];
    }
    uploadedImages.value = [];
    await nextTick();
    modelDropdownRef?.value?.handleSelectItem(props.currentSession.ai_model);
}, { immediate: true, deep: true });

// 监听自动滚动变化
watch(() => autoScroll.value, (newVal) => {
    if (newVal) {
        nextTick(() => {
            scrollToBottom(0);
        });
    }
});

// 监听消息列表变化，自动滚动到底部
watch(() => messageList.value.length, () => {
    if (autoScroll.value) {
        nextTick(() => {
            scrollToBottom();
        });
    }
});

// 生命周期
onMounted(() => {
    // 添加拖拽事件监听
    if (messageMainRef.value) {
        messageMainRef.value.addEventListener('dragenter', handleDragEnter);
        messageMainRef.value.addEventListener('dragover', handleDragOver);
        messageMainRef.value.addEventListener('dragleave', handleDragLeave);
        messageMainRef.value.addEventListener('drop', handleDrop);
    }

    // 添加粘贴事件监听
    document.addEventListener('paste', handlePaste);
});

onUnmounted(() => {
    // 清理拖拽事件监听
    if (messageMainRef.value) {
        messageMainRef.value.removeEventListener('dragenter', handleDragEnter);
        messageMainRef.value.removeEventListener('dragover', handleDragOver);
        messageMainRef.value.removeEventListener('dragleave', handleDragLeave);
        messageMainRef.value.removeEventListener('drop', handleDrop);
    }

    // 清理粘贴事件监听
    document.removeEventListener('paste', handlePaste);

    // 清理滚动节流定时器
    if (scrollThrottleTimer.value) {
        clearTimeout(scrollThrottleTimer.value);
        scrollThrottleTimer.value = null;
    }

    // 清理图片预览URL
    uploadedImages.value.forEach(img => {
        if (img.preview) URL.revokeObjectURL(img.preview);
    });
});

// 暴露方法
defineExpose({
    scrollToBottom,
    clearUploadedImages: () => {
        uploadedImages.value.forEach(img => {
            if (img.preview) URL.revokeObjectURL(img.preview);
        });
        uploadedImages.value = [];
    },
    loadMessages: loadSessionMessages, // 暴露消息加载方法
    clearMessages: () => {
        messageList.value = [];
        loadingType.value = 'none';
    }
});
</script>

